import React from 'react';
import ReactDOM from 'react-dom/client';
import './index.css';
import App from './App';
import { ToastProvider } from './contexts/ToastContext';
import { DarkModeProvider } from './contexts/DarkModeContext';
import CookieConsent from './components/CookieConsent';

const ensurePerformanceCompatibility = () => {
  if (typeof window === 'undefined' || !window.performance) return;

  const perf = window.performance;
  const noOp = () => {};

  // Some runtimes/tools expose partial Performance APIs. Guard them to avoid crashes.
  try {
    if (typeof perf.mark !== 'function') {
      Object.defineProperty(perf, 'mark', { value: noOp, configurable: true });
    }
    if (typeof perf.measure !== 'function') {
      Object.defineProperty(perf, 'measure', { value: noOp, configurable: true });
    }
    if (typeof perf.clearMarks !== 'function') {
      Object.defineProperty(perf, 'clearMarks', { value: noOp, configurable: true });
    }
    if (typeof perf.clearMeasures !== 'function') {
      Object.defineProperty(perf, 'clearMeasures', { value: noOp, configurable: true });
    }
  } catch (error) {
    // Ignore if Performance object is locked in the current browser runtime.
  }
};

ensurePerformanceCompatibility();

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(
  <React.StrictMode>
    <DarkModeProvider>
      <ToastProvider>
        <App />
        <CookieConsent />
      </ToastProvider>
    </DarkModeProvider>
  </React.StrictMode>
);
